#include <stdio.h>

int main(void) {
    int grid[][3] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};

    int rows = (int)(sizeof(grid) / sizeof(grid[0]));
    int cols = (int)(sizeof(grid[0]) / sizeof(grid[0][0]));

    for (int i = 0; i < rows; i++) {
        int total = 0;
        for (int j = 0; j < cols; j++) {
            total = total + grid[i][j];
        }
        printf("第 %d 行一共 %d 条喵\n", i, total);
    }
    return 0;
}

